      identityStatus: Value(identityStatus),
      diplomaStatus: Value(diplomaStatus),
      preferredInstitutionTypes: Value(preferredInstitutionTypes),
      preferredContractTypes: Value(preferredContractTypes),
      tutoringDays: Value(tutoringDays),
      tutoringSlots: Value(tutoringSlots),
      tutoringHours: Value(tutoringHours),
      workHours: Value(workHours),
      serviceTypes: Value(serviceTypes),
      mobility: mobility == null && nullToAbsent
