class SubjectRow extends DataClass implements Insertable<SubjectRow> {
  final String id;
  final String name;
  final String code;

  /// Cycles où la matière s'enseigne, séparés par des virgules :
  /// `PRIMAIRE`, `COLLEGE`, `LYCEE`, `SUPERIEUR`.
  ///
  /// Sert à ne proposer au professeur que les matières de son cycle — la
  /// liste complète mélange le droit et la lecture.
  final String cycles;
  final int sortOrder;
  final bool active;
  const SubjectRow({
    required this.id,
    required this.name,
    required this.code,
    required this.cycles,
    required this.sortOrder,
    required this.active,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['code'] = Variable<String>(code);
    map['cycles'] = Variable<String>(cycles);
    map['sort_order'] = Variable<int>(sortOrder);
    map['active'] = Variable<bool>(active);
    return map;
  }

  SubjectsCompanion toCompanion(bool nullToAbsent) {
    return SubjectsCompanion(
      id: Value(id),
      name: Value(name),
      code: Value(code),
      cycles: Value(cycles),
      sortOrder: Value(sortOrder),
      active: Value(active),
    );
  }

  factory SubjectRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return SubjectRow(
      id: serializer.fromJson<String>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      code: serializer.fromJson<String>(json['code']),
      cycles: serializer.fromJson<String>(json['cycles']),
      sortOrder: serializer.fromJson<int>(json['sortOrder']),
      active: serializer.fromJson<bool>(json['active']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'name': serializer.toJson<String>(name),
      'code': serializer.toJson<String>(code),
      'cycles': serializer.toJson<String>(cycles),
      'sortOrder': serializer.toJson<int>(sortOrder),
      'active': serializer.toJson<bool>(active),
    };
  }

  SubjectRow copyWith({
    String? id,
    String? name,
    String? code,
    String? cycles,
    int? sortOrder,
    bool? active,
  }) => SubjectRow(
    id: id ?? this.id,
    name: name ?? this.name,
    code: code ?? this.code,
    cycles: cycles ?? this.cycles,
    sortOrder: sortOrder ?? this.sortOrder,
    active: active ?? this.active,
  );
  SubjectRow copyWithCompanion(SubjectsCompanion data) {
    return SubjectRow(
      id: data.id.present ? data.id.value : this.id,
      name: data.name.present ? data.name.value : this.name,
      code: data.code.present ? data.code.value : this.code,
      cycles: data.cycles.present ? data.cycles.value : this.cycles,
      sortOrder: data.sortOrder.present ? data.sortOrder.value : this.sortOrder,
      active: data.active.present ? data.active.value : this.active,
    );
  }

  @override
  String toString() {
    return (StringBuffer('SubjectRow(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('code: $code, ')
          ..write('cycles: $cycles, ')
          ..write('sortOrder: $sortOrder, ')
          ..write('active: $active')
          ..write(')'))
        .toString();
  }

