class LevelRow extends DataClass implements Insertable<LevelRow> {
  final String id;
  final String name;
  final String code;

  /// PRIMARY, SECONDARY ou UNIVERSITY (§9).
  final String category;

  /// Cycle scolaire : `PRIMAIRE`, `COLLEGE`, `LYCEE`, `SUPERIEUR`.
  /// Plus fin que [category], qui ne distingue pas collège et lycée.
  final String cycle;

  /// En-tete de cycle (« Lycee »), pas une classe.
  ///
  /// Reste une cible valable pour une certification (« Mathematiques —
  /// Lycee ») ou une offre d'emploi, mais n'a rien a faire dans la liste des
  /// classes qu'on propose a un professeur : il choisit 11eme, 12eme ou
  /// Terminale, pas « Lycee ».
  final bool grouping;
  final int sortOrder;
  final bool active;
  const LevelRow({
    required this.id,
    required this.name,
    required this.code,
    required this.category,
    required this.cycle,
    required this.grouping,
    required this.sortOrder,
    required this.active,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['code'] = Variable<String>(code);
    map['category'] = Variable<String>(category);
    map['cycle'] = Variable<String>(cycle);
    map['grouping'] = Variable<bool>(grouping);
    map['sort_order'] = Variable<int>(sortOrder);
    map['active'] = Variable<bool>(active);
    return map;
  }

  LevelsCompanion toCompanion(bool nullToAbsent) {
    return LevelsCompanion(
      id: Value(id),
      name: Value(name),
      code: Value(code),
      category: Value(category),
      cycle: Value(cycle),
      grouping: Value(grouping),
      sortOrder: Value(sortOrder),
      active: Value(active),
    );
  }

  factory LevelRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return LevelRow(
      id: serializer.fromJson<String>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      code: serializer.fromJson<String>(json['code']),
      category: serializer.fromJson<String>(json['category']),
      cycle: serializer.fromJson<String>(json['cycle']),
      grouping: serializer.fromJson<bool>(json['grouping']),
      sortOrder: serializer.fromJson<int>(json['sortOrder']),
      active: serializer.fromJson<bool>(json['active']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'name': serializer.toJson<String>(name),
      'code': serializer.toJson<String>(code),
      'category': serializer.toJson<String>(category),
      'cycle': serializer.toJson<String>(cycle),
      'grouping': serializer.toJson<bool>(grouping),
      'sortOrder': serializer.toJson<int>(sortOrder),
      'active': serializer.toJson<bool>(active),
    };
  }

  LevelRow copyWith({
    String? id,
    String? name,
    String? code,
    String? category,
    String? cycle,
    bool? grouping,
    int? sortOrder,
    bool? active,
  }) => LevelRow(
    id: id ?? this.id,
    name: name ?? this.name,
    code: code ?? this.code,
    category: category ?? this.category,
    cycle: cycle ?? this.cycle,
    grouping: grouping ?? this.grouping,
    sortOrder: sortOrder ?? this.sortOrder,
    active: active ?? this.active,
  );
  LevelRow copyWithCompanion(LevelsCompanion data) {
    return LevelRow(
      id: data.id.present ? data.id.value : this.id,
      name: data.name.present ? data.name.value : this.name,
      code: data.code.present ? data.code.value : this.code,
      category: data.category.present ? data.category.value : this.category,
      cycle: data.cycle.present ? data.cycle.value : this.cycle,
      grouping: data.grouping.present ? data.grouping.value : this.grouping,
      sortOrder: data.sortOrder.present ? data.sortOrder.value : this.sortOrder,
      active: data.active.present ? data.active.value : this.active,
    );
  }

  @override
  String toString() {
    return (StringBuffer('LevelRow(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('code: $code, ')
          ..write('category: $category, ')
          ..write('cycle: $cycle, ')
