    this.website,
    this.foundedYear,
    this.ownership,
    this.academicSystem,
    required this.degrees,
    required this.specialties,
    required this.facilities,
    this.managerRole,
    required this.neededSubjectIds,
    required this.priorities,
    this.teacherLocation,
    required this.workDays,
    this.workStart,
    this.workEnd,
    this.maxDistance,
  });
