class AiCourseRow extends DataClass implements Insertable<AiCourseRow> {
  final String id;
  final String ownerId;

  /// Même identifiant pour toutes les versions d'un cours.
  final String courseId;
  final int version;
  final String title;
  final String courseJson;

  /// Word d'abord : c'est le fichier que le professeur rouvre et modifie.
  final String? docxPath;

  /// Excel en second, pour les tableaux d'exercices et le calendrier.
  final String? xlsxPath;

  /// Généré sans IA, en mode démonstration.
  final bool demo;
  final DateTime createdAt;
  const AiCourseRow({
    required this.id,
    required this.ownerId,
    required this.courseId,
    required this.version,
    required this.title,
    required this.courseJson,
    this.docxPath,
    this.xlsxPath,
    required this.demo,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['owner_id'] = Variable<String>(ownerId);
    map['course_id'] = Variable<String>(courseId);
    map['version'] = Variable<int>(version);
    map['title'] = Variable<String>(title);
    map['course_json'] = Variable<String>(courseJson);
    if (!nullToAbsent || docxPath != null) {
      map['docx_path'] = Variable<String>(docxPath);
    }
    if (!nullToAbsent || xlsxPath != null) {
      map['xlsx_path'] = Variable<String>(xlsxPath);
    }
    map['demo'] = Variable<bool>(demo);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  AiCoursesCompanion toCompanion(bool nullToAbsent) {
    return AiCoursesCompanion(
      id: Value(id),
      ownerId: Value(ownerId),
      courseId: Value(courseId),
      version: Value(version),
      title: Value(title),
      courseJson: Value(courseJson),
      docxPath: docxPath == null && nullToAbsent
          ? const Value.absent()
          : Value(docxPath),
      xlsxPath: xlsxPath == null && nullToAbsent
          ? const Value.absent()
          : Value(xlsxPath),
      demo: Value(demo),
      createdAt: Value(createdAt),
    );
  }

  factory AiCourseRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return AiCourseRow(
      id: serializer.fromJson<String>(json['id']),
      ownerId: serializer.fromJson<String>(json['ownerId']),
      courseId: serializer.fromJson<String>(json['courseId']),
